/// Registered customer accounts with email/password authentication
/// credentials for product browsing, ordering, and reviews. Customers are
/// the primary consumer actors in the platform who can browse products,
/// create wishlists, add items to cart, place orders, write reviews, and
/// manage their profiles and addresses.
///
/// Each customer account requires email verification during registration and
/// maintains authentication credentials for secure platform access. Customer
/// profiles include display name and phone number for personalization and
/// communication purposes. When customers delete their accounts, their
/// profile information is removed but order history and reviews are
/// preserved for seller records and legal compliance.
///
/// This table serves as the canonical identity record for customers across
/// the platform and is referenced by orders, reviews, wishlists, and address
/// management systems. {@link ecommerce_customer_sessions} tracks login
/// sessions, {@link ecommerce_customer_password_resets} handles credential
/// recovery, and {@link ecommerce_customer_email_verifications} manages
/// registration confirmation.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's email address used for authentication and communication. Must
  /// be unique across all customer accounts.
  email String

  /// Securely hashed password for customer authentication. Stored using
  /// industry-standard hashing algorithms.
  password_hash String

  /// Customer's display name shown throughout the platform for personalization
  /// and identification.
  display_name String

  /// Customer's phone number for order notifications and account verification
  /// purposes.
  phone_number String

  /// Timestamp when the customer account was created during registration.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was last updated, including profile
  /// changes.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was deleted, enabling soft deletion
  /// while preserving order history.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  sessions ecommerce_customer_sessions[]
  passwordResets ecommerce_customer_password_resets[]
  emailVerifications ecommerce_customer_email_verifications[]
  auditLogs ecommerce_audit_logs[]
  dataSnapshots ecommerce_data_snapshots[]
  platformEvents ecommerce_platform_event_of_customers[]
  metadataRegistryRelationships ecommerce_metadata_registry_relationship_of_customers[]
  variantSnapshots ecommerce_variant_snapshots[]
  shoppingCarts ecommerce_shopping_carts[]
  orders ecommerce_orders[]
  deliveryConfirmations ecommerce_delivery_confirmations[]
  paymentTransactions ecommerce_payment_transactions[]
  cancellationRequests ecommerce_cancellation_requests[]
  refundRequests ecommerce_refund_requests[]
  refundRequestModificationSnapshots ecommerce_refund_request_snapshots[]
  reviews ecommerce_reviews[]
  reviewVotes ecommerce_review_votes[]
  reviewReports ecommerce_review_reports[]
  reviewEdits ecommerce_review_edits[]
  reviewHelpfulVotes ecommerce_review_helpful_votes[]
  reviewFlags ecommerce_review_flags[]
  administratorPromotionRequests ecommerce_administrator_promotions[]
  administrativeActions ecommerce_administrative_action_of_customers[]
  userBans ecommerce_admin_user_ban_of_customers[]

  @@unique([email])
  @@index([created_at])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

