/// Password reset tokens with expiration for customer account password
/// recovery.
///
/// This table stores temporary password reset tokens that allow customers to
/// securely reset their passwords. Each token is uniquely generated and has
/// a limited validity period to ensure security. The system tracks token
/// usage to prevent reuse and maintains audit trails for security
/// monitoring.
///
/// Tokens are linked to specific customer accounts and include expiration
/// timestamps to enforce time-limited access. Once a token is used or
/// expires, it becomes invalid for future password reset attempts. This
/// approach ensures secure password recovery while preventing unauthorized
/// access attempts.
///
/// {@link ecommerce_customers.id}
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_customer_password_resets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer account requesting password reset. {@link ecommerce_customers.id}
  ecommerce_customer_id String @db.Uuid

  /// Unique password reset token generated for secure authentication.
  token String

  /// Timestamp when the password reset token expires and becomes invalid.
  expires_at DateTime @db.Timestamptz

  /// Timestamp when the password reset token was successfully used. Null if
  /// unused.
  used_at DateTime? @db.Timestamptz

  /// Timestamp when the password reset token was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the password reset token record was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ecommerce_customers @relation(fields: [ecommerce_customer_id], references: [id], onDelete: Cascade)

  @@unique([token])
  // spellchecker: ignore-next-line
  @@index([ecommerce_customer_id, created_at], map: "ecommerce_customer_password_resets_ecommerce_customer__bc3110fa")
  @@index([expires_at])
}

/// Seller accounts with email/password authentication credentials for
/// product management and order processing.
///
/// This table stores the core identity information for sellers on the
/// platform, including authentication credentials, shop profile details, and
/// account status tracking. Sellers must register with email and password,
/// and their accounts require administrator approval before they can sell
/// products. The table supports the complete seller lifecycle from
/// registration through active selling to account deletion with proper
/// constraints.
///
/// Sellers are managed through {@link ecommerce_seller_sessions} for
/// authentication sessions, {@link ecommerce_seller_password_resets} for
/// credential recovery, and {@link ecommerce_seller_email_verifications} for
/// registration confirmation. Seller profile changes are tracked through
/// {@link ecommerce_seller_profile_snapshots} for data integrity.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ecommerce_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller's email address used for authentication and communication. Must be
  /// unique across all seller accounts.
  email String

  /// Hashed password for seller authentication using secure hashing algorithm.
  password_hash String

  /// Official name of the seller's shop as displayed to customers.
  shop_name String

  /// Optional description of the seller's shop for customer information.
  shop_description String?

  /// URL to the seller's shop logo image for branding purposes.
  logo_image_url String? @db.VarChar(80000)

  /// Current status of the seller account: 'pending_approval', 'approved',
  /// 'rejected', 'suspended', or 'active'.
  account_status String

  /// Reason provided by administrator for approval or rejection decision.
  approval_reason String?

  /// Timestamp when the seller account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the seller account was last updated.
  updated_at DateTime @db.Timestamptz

