  system_setting_id String? @db.Uuid

  /// Reference to related audit log entries. {@link ecommerce_audit_logs.id}
  audit_log_id String? @db.Uuid

  /// Reference to database migration records. {@link
  /// ecommerce_db_migrations.id}
  db_migration_id String? @db.Uuid

  /// Unique identifier for the schema or entity being tracked.
