  dbMigration ecommerce_db_migrations? @relation(fields: [db_migration_id], references: [id], onDelete: Cascade)

  fieldDefinitions ecommerce_metadata_registry_field_definitions[]
  relationships ecommerce_metadata_registry_relationships[]
  categoryRelationships ecommerce_metadata_registry_relationship_of_categories[]

  @@index([system_setting_id])
  @@index([audit_log_id])
  @@index([db_migration_id])

  @@unique([schema_name, schema_version])
  @@index([created_at])
  @@index([is_active])
