  @@index([requesting_user_id, created_at], map: "ecommerce_administrator_promotions_requesting_user_id__338da080")
  // spellchecker: ignore-next-line
  @@index([approving_super_administrator_id, approved_at], map: "ecommerce_administrator_promotions_approving_super_adm_05c46080")
  @@index([request_reason(ops: raw("gin_trgm_ops"))], type: Gin)
