  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller        ecommerce_sellers         @relation(fields: [ecommerce_seller_id], references: [id], onDelete: Cascade)
  // spellchecker: ignore-next-line
  administrator ecommerce_administrators? @relation(fields: [ecommerce_administrator_id], references: [id], onDelete: Cascade, map: "ecommerce_seller_approval_queues_ecommerce_administrat_1065e3cc")

  approvalResponses ecommerce_seller_approval_responses[]

  @@unique([ecommerce_seller_id])
  @@index([status, submission_date])
  // spellchecker: ignore-next-line
  @@index([ecommerce_administrator_id, status], map: "ecommerce_seller_approval_queues_ecommerce_administrat_ff50624c")
  @@index([submission_date])
  @@index([rejection_reason(ops: raw("gin_trgm_ops"))], type: Gin)
